spec.expr:
topk(
  5,
  histogram_quantile(
    0.95,
    sum by (uri, le)(
      rate(
        http_server_requests_seconds_bucket{
          uri!~"/actuator.*"
        }[5m]
      )
    )
  ) * 1000
)

topk(
  5,
  sum by (uri)(
    increase(
      http_server_requests_seconds_count{
        outcome="SERVER_ERROR",
        uri!~"/actuator.*"
      }[5m]
    )
  )
)

topk(
  5,
  sum by (uri)(
    increase(
      http_server_requests_seconds_count{
        uri!~"/actuator.*"
      }[5m]
    )
  )
)

histogram_quantile(
  0.95,
  sum(
    rate(
      http_server_requests_seconds_bucket{
        uri!~"/actuator.*"
      }[5m]
    )
  ) by (le)
)

histogram_quantile(
  0.99,
  sum(
    rate(
      http_server_requests_seconds_bucket{
        uri!~"/actuator.*"
      }[5m]
    )
  ) by (le)
)

100 *
sum(
  rate(
    http_server_requests_seconds_count{
      status=~"5..",
      uri!~"/actuator.*"
    }[5m]
  )
)
/
sum(
  rate(
    http_server_requests_seconds_count{
      uri!~"/actuator.*"
    }[5m]
  )
)
